using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Geometry.AlgebraicBoundary;

internal sealed class InteriorCubicFactorDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Cubic entire-boundary equations on compact convex bodies.",
        Blocks(
            Paragraph(Text("Let B be a compact convex subset of a finite real coordinate space, let a be an interior point, and let p be a nonzero real multivariate polynomial of total degree at most three. Suppose p vanishes at every point of the entire boundary and also at a. Then the actual Frechet derivative L=Dp(a) is nonzero. There is a nonzero polynomial g such that p(x)=L(x-a)g(x) for every x, with deg(g)+1=deg(p), and g vanishes on the entire boundary.")),
            Paragraph(Text("For every nonzero vector v, the translated convex gauge constructs two actual boundary points a+alpha v and a+beta v with alpha<0<beta. The polynomial obtained by substituting a+tv has degree at most deg(p), and its linear coefficient is L(v). When L(v)=0, its zero constant and linear coefficients give a double zero at t=0. The two distinct nonzero boundary roots then force the restriction to vanish identically. The zero direction is included separately. Thus p vanishes on the entire affine hyperplane L(x-a)=0. If L were zero, p would vanish everywhere, contrary to polynomial function extensionality and p being nonzero.")),
            Paragraph(Text("The linear polynomial l representing L(x-a) is constructed in the same coordinates. Choose v with L(v)=1 and substitute x-l(x)v into p. This polynomial vanishes everywhere because the substituted points lie on the actual affine hyperplane, so it is the zero polynomial. In the quotient by the ideal generated by l, this substitution fixes every coordinate. Therefore p belongs to that principal ideal, giving a genuine polynomial factorization p=lg. Polynomial total degree is additive for these nonzero factors, and l has degree one. The entire-boundary factor deletion theorem then applies to the continuous polynomial g.")),
            Paragraph(Text("From any nonzero entire-boundary equation of degree at most three, choose a nonzero equation of minimum total degree among all entire-boundary equations. The factor theorem excludes every interior zero of that minimum equation. If the body has nonempty interior, continuity and convex connectedness show that its sign is constant there; choose its sign once so it is strictly positive everywhere in the interior.")),
            Paragraph(Text("The original-body statement retains an arbitrary real normed carrier E, an arbitrary continuous linear coordinate equivalence e from E to the finite coordinate space, and the original compact convex set B in E. The polynomial at an original point x is evaluated at e(x). The coordinate homeomorphism transports the entire frontier and interior, and minimum degree is compared against every polynomial vanishing on the original entire frontier. No local boundary patch, smoothness, irreducibility, supplied factorization or supplied minimum equation is used.")),
            Paragraph(Text("For an arbitrary original real normed carrier E with continuous linear coordinates c, a closed salient cone C, and a homogeneous entire-boundary polynomial p of degree d at most three, fix any original interior direction e with p(c(e)) nonzero. The actual restriction is q_x(t)=p(c(te-x)). Its top coefficient is exactly p(c(e)), so its degree is exactly d for every original x. Off the axis, the two actual closed-ray endpoints supply two distinct real roots; polynomial division by one linear factor leaves degree at most two with the second root, which gives complete splitting into real linear factors. On the axis x=se, the exact polynomial identity is q_x=p(c(e))(X-s)^d, including x=0 and every repeated root. Splitting retains multiplicities; it is stronger than merely listing two real roots.")))));
}
